import { useEffect, useState } from 'react';
import {
  ActivityIndicator,
  ScrollView,
  StyleSheet,
  Text,
  View,
} from 'react-native';
import { AppHeader } from '@/components/AppHeader';
import { Eyebrow, Sans, Serif } from '@/components/ui';
import { amountInWords, shortDate } from '@/lib/orders';
import { supabase } from '@/lib/supabase';
import { useParams } from '@/navigation';
import { colors, fonts } from '@/theme';

// The boutique's GST tax invoice for one part of an order, generated by the
// same generate-invoice function as the website (which prints it).
type Address = {
  address_line1?: string;
  address_line2?: string;
  city?: string;
  pincode?: string;
} | null;

interface Invoice {
  invoice_number: string;
  issued_at: string;
  order_number: string | null;
  order_date: string | null;
  subtotal: number;
  shipping_cost: number;
  discount_code: string | null;
  discount_amount: number;
  taxable_value: number | null;
  cgst_amount: number;
  sgst_amount: number;
  igst_amount: number;
  tax_amount: number;
  total: number;
  supply_type: 'intra_state' | 'inter_state' | null;
  seller_name: string;
  seller_legal_name: string | null;
  seller_gstin: string | null;
  seller_address: Address;
  seller_state: string | null;
  billing_name: string;
  billing_address: Address;
  billing_state: string | null;
}

interface Line {
  line_no: number;
  description: string;
  hsn_code: string | null;
  size: string | null;
  color: string | null;
  quantity: number;
  unit_price: number;
  discount: number;
  taxable_value: number;
  gst_rate: number;
  cgst_amount: number;
  sgst_amount: number;
  igst_amount: number;
  total: number;
}

const money = (n: number) =>
  `₹${Number(n).toLocaleString('en-IN', {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  })}`;
const addressLines = (a: Address) =>
  a
    ? [
        [a.address_line1, a.address_line2].filter(Boolean).join(', '),
        [a.city, a.pincode].filter(Boolean).join(' - '),
      ]
        .filter(Boolean)
        .join('\n')
    : '';

export default function InvoiceScreen() {
  const { id } = useParams<'Invoice'>();
  const [invoice, setInvoice] = useState<Invoice | null>(null);
  const [lines, setLines] = useState<Line[]>([]);
  const [ewb, setEwb] = useState<
    { ewb_number: string; ewb_date: string | null }[]
  >([]);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    supabase.functions
      .invoke('generate-invoice', { body: { vendor_order_id: id } })
      .then(async ({ data, error: e }) => {
        if (e || !data?.invoice) {
          let msg = 'Could not generate invoice';
          try {
            msg = (await (e as any)?.context?.json?.())?.error ?? msg;
          } catch {
            // no body
          }
          return setError(msg);
        }
        setInvoice(data.invoice);
        setLines(data.lines ?? []);
        setEwb(data.eway_bills ?? []);
      });
  }, [id]);

  const intra = invoice?.supply_type !== 'inter_state';

  return (
    <View style={styles.flex}>
      <AppHeader back title="Tax invoice" />
      {error ? <Sans style={styles.error}>{error}</Sans> : null}
      {!invoice && !error ? (
        <ActivityIndicator color={colors.primary} style={styles.spinner} />
      ) : null}
      {invoice ? (
        <ScrollView contentContainerStyle={styles.body}>
          <View style={styles.card}>
            <Serif style={styles.title}>Tax Invoice</Serif>
            <Row label="Invoice no." value={invoice.invoice_number} />
            <Row label="Invoice date" value={shortDate(invoice.issued_at)} />
            {invoice.order_number ? (
              <Row label="Order" value={invoice.order_number} />
            ) : null}
            {invoice.order_date ? (
              <Row label="Order date" value={shortDate(invoice.order_date)} />
            ) : null}
            {ewb.map(b => (
              <Row key={b.ewb_number} label="E-way bill" value={b.ewb_number} />
            ))}
          </View>

          <View style={styles.card}>
            <Eyebrow style={styles.head}>Sold by</Eyebrow>
            <Text style={styles.strong}>
              {invoice.seller_legal_name || invoice.seller_name}
            </Text>
            <Sans style={styles.text}>
              {addressLines(invoice.seller_address)}
            </Sans>
            {invoice.seller_state ? (
              <Sans style={styles.text}>State: {invoice.seller_state}</Sans>
            ) : null}
            {invoice.seller_gstin ? (
              <Sans style={styles.text}>GSTIN: {invoice.seller_gstin}</Sans>
            ) : null}
            <Eyebrow style={[styles.head, styles.gapTop]}>Bill to</Eyebrow>
            <Text style={styles.strong}>{invoice.billing_name}</Text>
            <Sans style={styles.text}>
              {addressLines(invoice.billing_address)}
            </Sans>
            {invoice.billing_state ? (
              <Sans style={styles.text}>State: {invoice.billing_state}</Sans>
            ) : null}
          </View>

          <View style={styles.card}>
            <Eyebrow style={styles.head}>Items</Eyebrow>
            {lines.map(l => (
              <View key={l.line_no} style={styles.line}>
                <Text style={styles.strong}>{l.description}</Text>
                <Sans style={styles.text}>
                  {[l.size, l.color].filter(Boolean).join(' / ')}
                  {l.hsn_code ? ` · HSN ${l.hsn_code}` : ''} · Qty {l.quantity}{' '}
                  × {money(l.unit_price)}
                </Sans>
                {l.discount > 0 ? (
                  <Row label="Discount" value={`- ${money(l.discount)}`} />
                ) : null}
                <Row label="Taxable value" value={money(l.taxable_value)} />
                {intra ? (
                  <>
                    <Row
                      label={`CGST ${Number(l.gst_rate) / 2}%`}
                      value={money(l.cgst_amount)}
                    />
                    <Row
                      label={`SGST ${Number(l.gst_rate) / 2}%`}
                      value={money(l.sgst_amount)}
                    />
                  </>
                ) : (
                  <Row
                    label={`IGST ${Number(l.gst_rate)}%`}
                    value={money(l.igst_amount)}
                  />
                )}
                <Row label="Line total" value={money(l.total)} strong />
              </View>
            ))}
          </View>

          <View style={styles.card}>
            <Row label="Subtotal" value={money(invoice.subtotal)} />
            {invoice.discount_amount > 0 ? (
              <Row
                label={`Discount${
                  invoice.discount_code ? ` (${invoice.discount_code})` : ''
                }`}
                value={`- ${money(invoice.discount_amount)}`}
              />
            ) : null}
            {invoice.shipping_cost > 0 ? (
              <Row label="Shipping" value={money(invoice.shipping_cost)} />
            ) : null}
            {invoice.taxable_value != null ? (
              <Row label="Taxable value" value={money(invoice.taxable_value)} />
            ) : null}
            {intra ? (
              <>
                <Row label="CGST" value={money(invoice.cgst_amount)} />
                <Row label="SGST" value={money(invoice.sgst_amount)} />
              </>
            ) : (
              <Row label="IGST" value={money(invoice.igst_amount)} />
            )}
            <View style={styles.rule} />
            <Row label="Total" value={money(invoice.total)} strong />
            <Sans style={styles.words}>{amountInWords(invoice.total)}</Sans>
          </View>
          <Sans style={styles.foot}>
            To print or save as PDF, open My orders on the AllBoutiqs website.
          </Sans>
        </ScrollView>
      ) : null}
    </View>
  );
}

function Row({
  label,
  value,
  strong,
}: {
  label: string;
  value: string;
  strong?: boolean;
}) {
  return (
    <View style={styles.row}>
      <Sans style={[styles.rowLabel, strong && styles.strong]}>{label}</Sans>
      <Sans style={strong ? styles.strong : undefined}>{value}</Sans>
    </View>
  );
}

const styles = StyleSheet.create({
  flex: { flex: 1, backgroundColor: colors.background },
  body: { paddingVertical: 8, paddingBottom: 32 },
  spinner: { marginTop: 48 },
  error: {
    textAlign: 'center',
    color: colors.destructive,
    marginTop: 48,
    paddingHorizontal: 24,
  },
  card: { backgroundColor: colors.ivory, padding: 16, marginBottom: 8 },
  title: { fontSize: 24, marginBottom: 10 },
  head: { color: colors.foreground, marginBottom: 6 },
  gapTop: { marginTop: 16 },
  strong: { fontFamily: fonts.sansSemi, color: colors.foreground },
  text: { fontSize: 13, lineHeight: 19, color: colors.mutedForeground },
  line: {
    paddingVertical: 10,
    borderBottomWidth: StyleSheet.hairlineWidth,
    borderBottomColor: colors.border,
  },
  row: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    paddingVertical: 2,
  },
  rowLabel: { color: colors.mutedForeground },
  rule: {
    height: StyleSheet.hairlineWidth,
    backgroundColor: colors.border,
    marginVertical: 8,
  },
  words: {
    fontSize: 12,
    color: colors.mutedForeground,
    marginTop: 6,
    fontStyle: 'italic',
  },
  foot: {
    fontSize: 12,
    color: colors.mutedForeground,
    textAlign: 'center',
    marginTop: 12,
    paddingHorizontal: 24,
  },
});
